def _extract_loan_details(self, message: str) -> tuple[str, float]:
    """Extract desired loan type and amount from user message."""
    message_lower = message.lower()

    loan_type = "general"
    type_keywords = {
        "sba": "SBA 7(a)",
        "504": "SBA 504",
        "term loan": "Term Loan",
        "line of credit": "Line of Credit",
        "loc": "Line of Credit",
        "equipment": "Equipment Financing",
        "invoice": "Invoice Factoring",
        "factoring": "Invoice Factoring",
        "merchant cash": "MCA",
        "mca": "MCA",
        "commercial real estate": "Commercial Real Estate",
        "cre": "Commercial Real Estate",
        "microloan": "Microloan",
        "working capital": "Line of Credit",
    }
    for keyword, lt in type_keywords.items():
        if keyword in message_lower:
            loan_type = lt
            break

    amount = 0.0
    import re
    amount_patterns = [
        r"\$\s*([\d,]+(?:\.\d+)?)\s*(?:k|K)",
        r"\$\s*([\d,]+(?:\.\d+)?)\s*(?:m|M)",
        r"\$\s*([\d,]+(?:\.\d+)?)",
        r"([\d,]+(?:\.\d+)?)\s*(?:thousand|k)\b",
        r"([\d,]+(?:\.\d+)?)\s*(?:million|m)\b",
        r"([\d,]+)\s*dollars",
    ]
    for pattern in amount_patterns:
        match = re.search(pattern, message, re.IGNORECASE)
        if match:
            raw = match.group(1).replace(",", "")
            amount = float(raw)
            if "k" in pattern.lower() or "thousand" in pattern:
                amount *= 1_000
            elif "m" in pattern.lower() or "million" in pattern:
                amount *= 1_000_000
            break

    if amount == 0:
        amount = 100_000

    return loan_type, amount

